    [Fact]public async Task ActualAppRbacPaymentInboxPublishesNativeAssignmentAndRefusesMissingSourcePurpose()
    {
        using var validation=CompanySalesInvoiceValidation.Enter();var (lifecycle,start)=await StartRecordedPaymentAssignment();var p=shared.Base.Posting;var native=p.Reviewed.Draft.Native;var grants=new[]{"Accounting.View","Accounting.ReviewSalesPaymentSource","Accounting.ReviewSalesPayment","Accounting.RecordSalesPaymentDecision","Workflow.Approve","Workflow.Execute"};using var rbac=new WorkflowInboxHttpTests.Fixture(actor:"controller");foreach(var grant in grants.Where(value=>value!="Accounting.View"))rbac.Repository.RoleClaims.Add(new(){RoleId="role",ClaimType="permission",ClaimValue=grant});rbac.Repository.SaveChanges();
        await using var host=await shared.Base.Baseline.NativeFixture.Receivable.Data.Invoice.Data.Start(permissions:grants,configure:(services,context)=>{rbac.Configure(services,context);context.Actor="controller";context.PolicyBinding=shared.Review.Current.Ledger.BindingRevision;context.StartBinding=shared.Review.Current.Ledger.BindingRevision;context.FixedProcess=lifecycle.Service;services.AddSingleton<IARService>(p.AR);services.AddScoped<CompanySalesReceivableReads>();services.AddSingleton(p.Reviewed.Draft.Service);services.AddSingleton<IProcessService>(lifecycle.Service);services.AddSingleton<ICrossPersonaTaskRouter>(lifecycle.Native.Router);});host.Client.DefaultRequestHeaders.Remove("X-Test-Actor");host.Client.DefaultRequestHeaders.Add("X-Test-Actor","controller");using var company=CompanyGLAccountHttpTests.Selected(actor:"controller",grants:grants);var inbox=new UnifiedTaskInboxService(new ApiClient(host.Client,Mock.Of<IFailureReporter>(),company));
        var result=await inbox.GetInboxAsync("ACCOUNTANT");var row=Assert.Single(result.CriticalTasks.Concat(result.HighPriorityTasks).Concat(result.NormalTasks));Assert.Equal("AR_PAYMENT",row.EntityType);Assert.Equal(WorkflowTaskRoute.For("COMPANY_ACCOUNTING",start.InstanceId,"AR_PAYMENT"),row.Route);Assert.Equal("SALES_PAYMENT_APPROVAL_REQUIRED",row.AccountingStepReview!.Eligibility);Assert.Equal("collector",row.AccountingStepReview.SourceMakerUserId);Assert.Equal("ConfiguredCompanyRole",row.AssignedRole);Assert.Equal(1,result.Counts.TotalPending);Assert.DoesNotContain("COMMAND_JSON",JsonSerializer.Serialize(result));Assert.Equal(0,native.Writes);
        await RenderPaymentLanding(result,company,row.Route);
        native.Source.Invocations.Clear();var claim=rbac.Repository.RoleClaims.Single(value=>value.ClaimValue=="Accounting.ReviewSalesPaymentSource");rbac.Repository.RoleClaims.Remove(claim);rbac.Repository.SaveChanges();host.Context.Permissions=grants.Where(value=>value!="Accounting.ReviewSalesPaymentSource").ToArray();var removed=await inbox.GetInboxAsync("ACCOUNTANT");Assert.Equal(0,removed.Counts.TotalPending);Assert.Empty(removed.CriticalTasks.Concat(removed.HighPriorityTasks).Concat(removed.NormalTasks));Assert.Equal(0,native.Writes);
    }
    private static async Task RenderPaymentLanding(UnifiedInbox result,Beep.OilandGas.Client.App.CompanyClientContext company,string route)
    {
        // Freeze the actual app-RBAC/native response solely for the renderer and its filters.
        var transport=new Mock<IUnifiedTaskInboxService>(MockBehavior.Strict);transport.Setup(value=>value.GetInboxAsync("ACCOUNTANT")).ReturnsAsync(CompanyInventorySourceReview.Copy(result));
        var personas=new Mock<IPersonaContextService>(MockBehavior.Strict);personas.Setup(value=>value.EnsureLoadedAsync()).Returns(Task.CompletedTask);personas.SetupGet(value=>value.CurrentPersona).Returns(new AppPersona{Code="ACCOUNTANT",Name="Accountant",DefaultRoute="/accounting/dashboard"});personas.SetupGet(value=>value.CurrentProfile).Returns(new AppUserPersona{UserId="controller",PersonaCode="ACCOUNTANT"});
        using var landingCompany=CompanyGLAccountHttpTests.Selected(actor:company.Selection!.UserId,grants:company.Selection.Permissions.ToArray());Assert.Equal(company.Selection.Scope,landingCompany.Selection!.Scope);
        using var state=new PersonaTaskInboxState(transport.Object,landingCompany,personas.Object);state.Start();await state.LoadAsync(["/accounting/dashboard"]);state.SelectSource("AR_PAYMENT");state.SelectRole("ConfiguredCompanyRole");state.SelectAccountingEvidence("SALES_PAYMENT_APPROVAL_REQUIRED");Assert.Single(state.VisibleRows);Assert.Equal(1,state.SelectedCounts.TotalPending);
        var services=new ServiceCollection();services.AddLogging();services.AddMudServices();services.AddSingleton<IJSRuntime,APInvoiceFinancialHttpTests.NoBrowser>();services.AddSingleton<NavigationManager,APInvoiceFinancialHttpTests.Navigation>();await using var provider=services.BuildServiceProvider();await using var renderer=new HtmlRenderer(provider,provider.GetRequiredService<ILoggerFactory>());
        await renderer.Dispatcher.InvokeAsync(async()=>{
            var root=await renderer.RenderComponentAsync<Beep.OilandGas.Web.Components.Workflow.PersonaAssignedWorkPanel>(ParameterView.FromDictionary(new Dictionary<string,object?>{{"Review",state},{"WorkspaceName","Accountant"}}));var html=root.ToHtmlString();Assert.Contains("Payment review/rejection assignments: 1",html);Assert.Contains("Payment decision needed: 1",html);Assert.Contains("Payment rejection to route: 0",html);Assert.Contains("Recorded payment reviewer required: 0",html);Assert.Contains("Original payment maker required: 0",html);Assert.Contains(route,html);Assert.Contains("record its independent financial/receipt decision first",html);
            state.SelectAccountingEvidence("SALES_PAYMENT_REJECTION_RECORDED");Assert.Empty(state.VisibleRows);Assert.Equal(0,state.EvidenceCount("SALES_PAYMENT_REJECTION_RECORDED"));Assert.Equal(1,state.SelectedCounts.TotalPending);state.SelectAccountingEvidence("SALES_PAYMENT_APPROVAL_REQUIRED");landingCompany.Clear();Assert.Null(state.Current);Assert.Empty(state.VisibleRows);
        });
    }
