        await using var host=await shared.Base.Baseline.NativeFixture.Receivable.Data.Invoice.Data.Start(permissions:grants,configure:(services,context)=>{context.Actor="collector";context.PolicyBinding=scope.BindingRevision;context.StartBinding=scope.BindingRevision;context.FixedProcess=lifecycle.Service;services.AddSingleton<IARService>(p.AR);services.AddScoped<CompanySalesReceivableReads>();services.AddSingleton(p.Reviewed.Draft.Service);});host.Client.DefaultRequestHeaders.Remove("X-Test-Actor");host.Client.DefaultRequestHeaders.Add("X-Test-Actor","collector");using var company=CompanyGLAccountHttpTests.Selected(actor:"collector",grants:grants);var accounting=CompanyGLAccountHttpTests.Client(host.Client,company);var processes=CompanySalesReceivableWorkflowTests.Fixture.Processes(host,company);using var state=new CompanySalesReceivableWorkspaceState(company);state.AttachOwner(new object());using var handoff=new CompanyAccountingHandoffState(company);
